package fitnessrules

import "testing"

// TestPythonExecRuleSeesAJoinedInterpreterPath: a Python interpreter named as a
// string literal inside the one nested call the rule allows (filepath.Join of an
// install folder and the interpreter's file name) is a Go test starting Python.
// The spelling is held with an escape so this file does not trip the rule itself.
func TestPythonExecRuleSeesAJoinedInterpreterPath(t *testing.T) {
	rules := loadRules(t, repoRoot(t))
	r, ok := rules["no Go code starts a Python interpreter"]
	if !ok {
		t.Fatal("fitness.yaml has no rule named \"no Go code starts a Python interpreter\"")
	}
	text := "cmd := exec.Command(filepath.Join(pyHome, \"p\x79thon.exe\"), script)"
	if fired, skipped := r.fires("tools/launch_test.go", text); !fired {
		t.Errorf("the rule stays quiet on %s (skipped %v)", text, skipped)
	}
}
